import os
import unicodedata
from flask import Flask, request, send_file, abort, session
from werkzeug.utils import secure_filename
from werkzeug.security import generate_password_hash, check_password_hash
import hashlib
import hmac
import re

app = Flask(__name__)
app.secret_key = os.urandom(32)

UPLOAD_DIR = '/var/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode('utf-8') if isinstance(a, str) else a,
                               b.encode('utf-8') if isinstance(b, str) else b)

def is_safe_path(base_dir, requested_path):
    """Check if the resolved path is within the base directory."""
    # Resolve to absolute path
    abs_base = os.path.realpath(base_dir)
    abs_path = os.path.realpath(requested_path)
    # Ensure the path starts with the base directory
    return abs_path.startswith(abs_base + os.sep) or abs_path == abs_base

def sanitize_filename(filename):
    """Remove dangerous characters and validate filename."""
    # First normalize unicode to prevent bypass via equivalent forms
    filename = unicodedata.normalize('NFC', filename)
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Check for path traversal sequences
    if '..' in filename or '/' in filename or '\\' in filename:
        return None
    # Check extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    # Additional: only allow printable ASCII + common unicode letters
    if not all(c.isprintable() and c not in '<>:"|?*' for c in filename):
        return None
    return filename

def normalize_for_storage(filename):
    """Normalize unicode characters for consistent storage."""
    # NFC normalization for consistent representation
    return unicodedata.normalize('NFC', filename)

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        abort(400)
    username = data.get('username', '')
    password = data.get('password', '')
    # Verify against a salted, slow KDF (PBKDF2 via werkzeug).
    stored_hash = get_password_hash(username)
    if stored_hash and check_password_hash(stored_hash, password):
        session['user'] = username
        session['user_dir'] = os.path.join(UPLOAD_DIR, secure_filename(username))
        return {'status': 'ok'}
    abort(401)

def get_password_hash(username):
    """Retrieve stored password hash for user.

    In production these salted PBKDF2 hashes would be loaded from a
    persistent user store rather than generated at runtime.
    """
    users_db = {
        'alice': generate_password_hash('alice_secret_pw_2024'),
        'bob': generate_password_hash('bob_secret_pw_2024'),
    }
    return users_db.get(username)

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'user' not in session:
        abort(401)
    if 'file' not in request.files:
        abort(400)
    f = request.files['file']
    if not f.filename:
        abort(400)

    # Sanitize includes normalization first, then checks
    clean_name = sanitize_filename(f.filename)
    if clean_name is None:
        abort(400, 'Invalid filename')

    # Build full path
    user_dir = session['user_dir']
    os.makedirs(user_dir, exist_ok=True)
    full_path = os.path.join(user_dir, clean_name)

    # Verify path safety
    if not is_safe_path(user_dir, full_path):
        abort(403, 'Path traversal detected')

    f.save(full_path)
    return {'status': 'uploaded', 'filename': clean_name}

@app.route('/download/<filename>')
def download_file(filename):
    if 'user' not in session:
        abort(401)

    # Sanitize includes normalization
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        abort(400, 'Invalid filename')

    user_dir = session['user_dir']
    full_path = os.path.join(user_dir, clean_name)

    if not is_safe_path(user_dir, full_path):
        abort(403)

    if not os.path.isfile(full_path):
        abort(404)

    return send_file(full_path)

@app.route('/search')
def search_files():
    if 'user' not in session:
        abort(401)

    query = request.args.get('q', '')
    if not query or len(query) > 100:
        abort(400)

    user_dir = session['user_dir']
    if not os.path.isdir(user_dir):
        return {'results': []}

    # Normalize query for consistent matching
    norm_query = unicodedata.normalize('NFC', query)

    results = []
    for fname in os.listdir(user_dir):
        if norm_query.lower() in fname.lower():
            results.append(fname)

    return {'results': results}

@app.route('/rename', methods=['POST'])
def rename_file():
    if 'user' not in session:
        abort(401)

    data = request.get_json()
    if not data:
        abort(400)

    old_name = data.get('old_name', '')
    new_name = data.get('new_name', '')

    # Sanitize both names (normalization happens inside sanitize_filename)
    clean_old = sanitize_filename(old_name)
    clean_new = sanitize_filename(new_name)

    if clean_old is None or clean_new is None:
        abort(400, 'Invalid filename')

    user_dir = session['user_dir']
    old_path = os.path.join(user_dir, clean_old)
    new_path = os.path.join(user_dir, clean_new)

    if not is_safe_path(user_dir, old_path) or not is_safe_path(user_dir, new_path):
        abort(403)

    if not os.path.isfile(old_path):
        abort(404)

    os.rename(old_path, new_path)
    return {'status': 'renamed', 'new_name': clean_new}

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
